window.ARTICLES=[{"title": "Your AI Agent Needs a Bouncer", "url": "https://medium.com/@tituslhy/your-ai-agent-needs-a-bouncer-f115d5ddac55", "date": "2026-10-16", "words": 2153, "dek": "Experiments with using Jev, a fast decision model, to classify messy user queries and route them through a multi-agent workflow for clarification, decomposition, or rewriting.", "open": "The artificial intelligence industry has spent the past few years racing to build increasingly intelligent large language models (LLMs). LLMs got bigger, got better at reasoning and now accept longer context windows. Then, on 15 September 2026, something rather different arrived.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*NK8bGYaaCPoI0lv2drwh8g.png", "cap": null, "mins": 9}, {"title": "Introducing stablecoins", "url": "https://medium.com/@tituslhy/introducing-stablecoins-2b3e63e6c5f1", "date": "2026-10-10", "words": 2796, "dek": "Explains how fiat-backed and crypto-collateralized stablecoins attempt to maintain dollar pegs, illustrating issuance, redemption, market pricing, and failure risks with a blockchain implementation.", "open": "Cryptocurrency has a volatility problem. The entire construct of cryptocurrency is trust-based through the use of blockchain. Unlike fiat currencies like USD, cryptocurrencies are unregulated, but can be exchanged for fiat currencies. However, a quick google search shows the price fluctuation of bitcoin: Imagine receiving your salary in cryptocurrency, only to discover that your purchasing power has fallen by 10% before you’ve paid your bills.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*IrGDxHop8Y-GBfiwRHMb1w@2x.jpeg", "cap": null, "mins": 11}, {"title": "Flash loan attacks on smart contracts", "url": "https://medium.com/@tituslhy/flash-loan-attacks-on-smart-contracts-cb08c72408bd", "date": "2026-10-04", "words": 1860, "dek": "Demonstrates in code how flash loans can manipulate thin AMM spot prices to trigger unfair lending liquidations, and motivates oracle defenses using independent price reports.", "open": "Last time, I compared smart contracts to vending machines: put in $2, press B4, get a Snickers. No clerk, no judgment calls. A smart contract is code at an address that gives the same output every time it’s called, and it can call other contracts. We built three of them.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*Km0coZYZiINJvKPMfMcRzA@2x.jpeg", "cap": null, "mins": 7}, {"title": "Introducing Smart Contracts", "url": "https://medium.com/@tituslhy/introducing-smart-contracts-340c20cbe672", "date": "2026-09-14", "words": 2552, "dek": "Explains how deterministic smart contracts execute transactions on a blockchain, demonstrates swap and lending contracts, and uses oracles to supply off-chain data.", "open": "My odyssey into blockchain has been getting progressively more interesting. What started as curiosity to understand how Bitcoin works has turned into a series of articles where I keep opening increasingly suspicious-looking boxes and asking, _“Okay, but what actually happens inside?”_ So far I’ve covered how blocks get proposed (PoW, then PoS), how a Merkle tree lets you prove one credential belongs to a much bigger set without hauling out the whole set, how permissioned chains handle endorsement and stale-state co", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*vz63BE9s0G63Jh642ddKQQ@2x.jpeg", "cap": null, "mins": 10}, {"title": "Introducing mempools - The one time gossip pays off", "url": "https://medium.com/@tituslhy/introducing-mempools-the-one-time-gossip-pays-off-9fbc92701f70", "date": "2026-09-04", "words": 2217, "dek": "Explains how public blockchains use node-local mempools and probabilistic transaction gossip to form block proposals, and how slots and attestations help resolve competing views caused by propagation delays.", "open": "In my previous article on permissioned chains, we encountered the problem of race conditions. In a system where transactions are constantly being proposed against shared state, two perfectly legitimate transactions can race against each other. One may change the state before the other reaches validation, making the second transaction stale.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*3TviPmaI8yOX4v5_jtbtrQ.png", "cap": null, "mins": 9}, {"title": "Introducing permissioned chains", "url": "https://medium.com/@tituslhy/introducing-permissioned-chains-1d8a71f5b09a", "date": "2026-08-30", "words": 2598, "dek": "Builds a Hyperledger Fabric-inspired permissioned blockchain with registered organizations, versioned key-value state, transaction endorsements, ordering, and validation for handling concurrent updates.", "open": "In my previous articles, I covered blockchains that operate using (i) proof-of-work (PoW), aka mining, and (ii) proof-of-stake (PoS). In the third article, I extended the PoS blockchain with Merkle trees to explore how the same ideas can be used to create tamper-evident educational credentials.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*dkv-5Lez5lAErm8uJxAxrQ.png", "cap": null, "mins": 10}, {"title": "Inside OpenCerts: How Merkle Trees Verify Singapore’s Digital Diplomas", "url": "https://medium.com/@tituslhy/inside-opencerts-how-merkle-trees-verify-singapores-digital-diplomas-61f60d13700e", "date": "2026-08-27", "words": 1927, "dek": "Explains how OpenCerts uses Merkle trees and Ethereum anchoring to verify individual digital diplomas without publishing the credentials or storing them on-chain.", "open": "If you’ve attended a Singapore university, you may have noticed something unusual about the digital copy of your diploma: instead of receiving a PDF, you might have received a file ending in .opencert. Open it in a text editor and things get even stranger. Instead of a beautifully formatted diploma, you’re greeted by what looks like a giant JSON object filled with fields, hashes, signatures and other decidedly _non-diploma-looking_ things.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*2WTXFCzpjB6RXafgosvdbA@2x.jpeg", "cap": null, "mins": 7}, {"title": "Proof-of-Stake: The Mining-Free Blockchain", "url": "https://medium.com/@tituslhy/proof-of-stake-the-mining-free-blockchain-ddae684ffec5", "date": "2026-08-21", "words": 2855, "dek": "Builds a toy proof-of-stake blockchain in Python, using stake-weighted validator selection, rewards, and slashing instead of mining to deter cheating.", "open": "In my previous article, I coded out a toy blockchain to introduce basic blockchain concepts. We learnt two important things: It wasn’t enough for a hacker to tamper with one block in the blockchain. Changing the contents of a block changes its hash. And because every block contains the previous block’s hash, changing one block breaks the chain from that point onwards.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*ULXDe3PuUQarxkfpNpqMjQ.png", "cap": "Proof-of-stake. Image generated by ChatGPT", "mins": 11}, {"title": "Understanding Blockchains from scratch", "url": "https://medium.com/@tituslhy/understanding-blockchains-from-scratch-f14c454af32f", "date": "2026-08-14", "words": 2688, "dek": "Builds a toy Python blockchain with SHA-256 hash chaining and proof-of-work mining to show how tampering is detected and competing transaction histories are resolved.", "open": "Have you ever wondered how cryptocurrency works without anyone being in charge? I did. Specifically: how can thousands of strangers around the world agree on who owns what — without a central bank keeping the ledger, and without having to trust one another? This article is my attempt to understand the answer the way I understand things best: by building one from scratch.", "desks": ["chain"], "img": "https://cdn-images-1.medium.com/max/1400/1*uaSq53IHPTw9hu-55VrbSw.png", "cap": null, "mins": 10}, {"title": "Building skilled agents", "url": "https://medium.com/@tituslhy/building-skilled-agents-835597b38be4", "date": "2026-08-09", "words": 2860, "dek": "Explains how to implement agent skills as progressively disclosed instructions in a LangChain agent, comparing file-based, remote, and tool-free setups and debugging execution with logging.", "open": "In October 2025, Anthropic taught the world how to build agents properly for the second time. The first lesson was Model Context Protocol. This one is agent skills. The problem skills solve is context overload. Want your agent to do 50 things? Great — give it 50 tools.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*mJ-LCLyXapbZm5ekxzU_JA@2x.jpeg", "cap": null, "mins": 12}, {"title": "A field guide to multi-agent architectures", "url": "https://medium.com/@tituslhy/a-field-guide-to-multi-agent-architectures-f6f8c689c406", "date": "2026-07-27", "words": 3117, "dek": "Explains five multi-agent architectures—hierarchical, workflow, swarm, blackboard, and actor-critic—and compares their coordination mechanisms and use cases with LangChain and LangGraph examples.", "open": "Every team building with LLMs eventually reaches the same moment. The first agent works. Then someone asks, _“What if we add another agent?”_ One agent becomes three. Three become eight. Before long, you’re no longer writing prompts — you are designing an organisation of AI workers that need to coordinate, share information, recover from failures and decide who should do what.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*lmBgEBfePFAvu5kHr7c-Fw.png", "cap": "Designing agent architectures. Image generated by ChatGPT", "mins": 13}, {"title": "A Second Note on Claude Code", "url": "https://medium.com/mitb-for-all/a-second-note-on-claude-code-c521245ffc35", "date": "2026-07-05", "words": 3138, "dek": "Explains how to configure Claude Code with modular and path-scoped instructions, event hooks, offline workflows, tracing, and plugins to customize coding assistance.", "open": "Authors’ Note: This article is jointly written by James Koh, PhD and Tituslhy (“Titus”). Since Titus’ previous Medium article on Claude Code, Titus and James have been comparing notes from their individual use of Claude Code. There were simply too many lessons , so here we are.", "desks": ["copilots"], "img": null, "cap": null, "mins": 12}, {"title": "Ground control to Antigravity", "url": "https://medium.com/@tituslhy/ground-control-to-antigravity-7056a6d58d0a", "date": "2026-06-24", "words": 2227, "dek": "The author evaluates Google Antigravity’s CLI, IDE, and orchestration tools as coding-agent alternatives to Claude Code by building a responsive jigsaw puzzle app and examining workflows, usage limits, and integrations.", "open": "In my previous article on Claude Code, I shared how I optimize my workflow to get the most out of its context window and token budget. Those techniques work well, but you might still run into usage limits. During the period when Anthropic was more aggressively throttling usage, the restrictions frequently coincided with my peak coding hours — 1pm–7pm GMT (9pm onwards in Singapore).", "desks": ["copilots"], "img": "https://cdn-images-1.medium.com/max/1400/1*CrihncZI8pCf2CVXVbsgTQ@2x.jpeg", "cap": "We have lift off. Image generated by ChatGPT and refined by Nano Banana", "mins": 10}, {"title": "So you want a personal AI assistant", "url": "https://medium.com/@tituslhy/so-you-want-a-personal-ai-assistant-4c6226e88017", "date": "2026-06-18", "words": 2864, "dek": "Introduces Hermes Agent, an open-source self-hosted AI framework, and explains installing it with local or cloud models for persistent assistance, coding, messaging, and automation.", "open": "Everyone wants a personal AI assistant these days. If you’ve been anywhere near the AI space recently, you’ve heard of OpenClaw. Its logo is a lobster claw. The internet ran with it. In China, there are mass “lobster gatherings” where people learn to install and use it.", "desks": ["copilots"], "img": "https://cdn-images-1.medium.com/max/1400/1*c8hD9pI6ltE4d5tXbKqJdQ@2x.jpeg", "cap": "A personal AI assistant can now be in anybody’s hands. Image generated by ChatGPT from author’s prompt", "mins": 12}, {"title": "How I use Claude Code", "url": "https://medium.com/@tituslhy/how-i-use-claude-code-3b1fd852305b", "date": "2026-06-16", "words": 2697, "dek": "Explains using Claude Code with context management, skills, permissions, and specialized agents to build a full-stack stock-analysis MCP service with interactive dashboards.", "open": "I want to start with a confession. The only terminal commands I personally typed to build a full-stack stock analysis service were uv init and uv add <package> Everything else — the architecture, the backend, the UI, the MCP tools, the debugging, the iteration — was Claude.", "desks": ["copilots"], "img": "https://cdn-images-1.medium.com/max/1400/1*OSSupz7dPXZU10wJKl_OPQ@2x.jpeg", "cap": "Claude code. Image generated by ChatGPT using Author’s Prompt", "mins": 11}, {"title": "How to be a data scientist in 2026 (and beyond)", "url": "https://medium.com/@tituslhy/how-to-be-a-data-scientist-in-2026-and-beyond-9b0b322c8e5a", "date": "2026-03-16", "words": 2870, "dek": "Examines how generative AI is reshaping data science roles and recommends practical skills such as systems thinking, shipping software, communicating ideas, and learning TypeScript.", "open": "In 2012, Harvard Business Review wrote an article acclaiming the data scientist as the sexiest job in the 21st century. Since then many have aspired to break into the field, but the nature of a data scientist has changed. Look into job descriptions across the board and you’ll realize a few things: 1.", "desks": ["career"], "img": "https://cdn-images-1.medium.com/max/1400/1*SenINSV3QrpQ3MmaEQ6tIQ.png", "cap": "A data scientist wears many hats. Image generated by Nano Banana", "mins": 11}, {"title": "Introducing Liquibase: How to version control your DB", "url": "https://medium.com/@tituslhy/introducing-liquibase-how-to-version-control-your-db-d5a08f764c09", "date": "2026-02-20", "words": 2257, "dek": "Demonstrates using Liquibase changelogs to version, apply, and roll back database schema migrations, including PostgreSQL setup and SQL, XML, YAML, and JSON formats.", "open": "Stop me if you’ve heard this one before. > It was supposed to be harmless. > One ALTER TABLE. > One deploy. > Five minutes. > Instead, production was down. > The migration script ran. > The table didn’t exist. > A stored procedure referenced the wrong schema. > No one was entirely sure which version of the database production was actually on.", "desks": ["swe"], "img": "https://cdn-images-1.medium.com/max/1400/1*QKuG5k14_B_fnNcPVabRyQ.png", "cap": "Time travelling with postgresql. Image generated by nano banana", "mins": 9}, {"title": "📱Would you like an app with that? — Introducing the ADK Framework", "url": "https://medium.com/@tituslhy/would-you-like-an-app-with-that-introducing-the-adk-framework-aead05a8b9cd", "date": "2026-02-10", "words": 2169, "dek": "Demonstrates building and deploying full-stack GenAI chat applications with Google ADK, covering agents, tracing, audio, model choices, A2A interoperability, and Cloud Run.", "open": "One of the biggest risks in GenAI projects isn’t model quality or infrastructure cost — it’s orphaned products. By the time an application reaches the finish line, users have often moved on. Requirements shift. New ideas emerge. What felt exciting at kickoff no longer solves the real problem.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*nZvzc17merXwGv2BrB8CXQ.png", "cap": "Introducing the Agent Development Kit. Image generated by Nano Banana", "mins": 9}, {"title": "Helm Charts: The Multi-Server Orchestra Conductor", "url": "https://medium.com/@tituslhy/helm-charts-the-multi-server-orchestra-conductor-18dc88665fc1", "date": "2026-02-01", "words": 4307, "dek": "Converts a Docker Compose application into a Helm chart and deploys it on Kubernetes with services, ingress, autoscaling, upgrades, and rollback.", "open": "_Docker Compose is great… until your app needs to survive the real world._ The considerations for developing an application and deploying an application are wildly different. During development, the goal is simple: > Make the code work. But during deployment, a new set of questions suddenly matter: - Traffic: Can your app survive hundreds (or thousands) of requests hitting it at once?", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*GdlUTFMt4xMy4xwtv1eoaQ.png", "cap": "Helm, Kubernetes and the yaml nightmare. Image generated by nano banana", "mins": 18}, {"title": "A second look at LangGraph: When “Command Sends” becomes “common sense”", "url": "https://medium.com/@tituslhy/a-second-look-at-langgraph-when-command-sends-becomes-common-sense-720a851cf8a8", "date": "2026-01-14", "words": 2526, "dek": "Shows how LangGraph’s Command and Send primitives simplify building an edgeless investment-analysis workflow with planning, human feedback, and specialized stock-analysis agents.", "open": "In my previous article introducing LangGraph, I described it as a low-level framework that requires manual construction of a graph to represent a multi-agent workflow. Each node represents a step, edges connect those steps, and execution flows by mutating a shared State object.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*Ka4HUXz9WBvqjGTqrOcqdw.png", "cap": "LangGraph: Day and night. Image generated by nano banana", "mins": 10}, {"title": "LangChain4j: Building generative AI applications in Java", "url": "https://medium.com/@tituslhy/langchain4j-building-generative-ai-applications-in-java-670ec3d6167d", "date": "2025-11-17", "words": 2383, "dek": "Demonstrates using LangChain4j in Java for LLM chat, streaming, structured output, and document-based retrieval-augmented generation, with setup guidance and comparison to Python LangChain.", "open": "In my last article on gRPC, I announced a hiatus from writing to focus on learning a new language: Java. Beyond being a staple in every corporation, I noticed that generative AI frameworks are beginning to make inroads into Java. For example, the A2A protocol and Google’s ADK framework are now available in Java.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*oE027PD3576u4H7jSRqmTw.png", "cap": "LangChain now has a Java sibling. Image generated by nano banana.", "mins": 10}, {"title": "LangChain 1.0 — A second look", "url": "https://medium.com/@tituslhy/langchain-a-second-look-6ed720e27fec", "date": "2025-10-25", "words": 2598, "dek": "Explains LangChain 1.0’s middleware-based context engineering and updated APIs for building agents and multi-agent systems, with examples of model invocation and middleware components.", "open": "In September 2025 the world stood still for a minute: LangChain announced a major rewrite of the LangChain and LangGraph frameworks. Instead of version 0.3, both frameworks are now 1.0. Announcements like these are terrifying — you’ve spent so much effort building your generative AI application, and you know LangChain rewrites have a habit of breaking everything.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*HqGQxPjr44OB-oOP-vttUA.png", "cap": "Using LangChain 1.0 vs LangChain 0.X is like night and day! Image generated by nano banana", "mins": 11}, {"title": "Nginx: The Single-Server Swiss Army Knife", "url": "https://medium.com/@tituslhy/nginx-the-single-server-swiss-army-knife-3445197f8f86", "date": "2025-10-22", "words": 3363, "dek": "Explains deploying a Chainlit app with Docker Compose and configuring Nginx as a reverse proxy and load balancer for multiple replicas, including WebSocket support.", "open": "The considerations for developing and deploying an application are vastly different. During development, the main goal is simple: make the code work. As long as it runs on your favorite localhost, life is good. But during deployment, a new set of questions arise: - Traffic: Can your app handle hundreds of requests hitting it at once?", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*Wvpqrnnj2rFKW6-rIuXNmA.png", "cap": "Introducing the world’s best software traffic controller. Image generated by Nano Banana", "mins": 13}, {"title": "A very simple introduction to gRPC", "url": "https://medium.com/@tituslhy/a-very-simple-introduction-to-grpc-6a666a039c03", "date": "2025-10-05", "words": 2179, "dek": "Walks through building a Python gRPC to-do backend with Protocol Buffers and SQL, then connecting it to FastAPI for REST endpoints and asynchronous batch operations.", "open": "FastAPI has become a staple in Python backends — and for good reason: it’s just awesome. I build all my API backends with it. In my previous article on concurrency and parallelism, I showed how to use asyncio, threading, and multiprocessing to handle tasks, threads, and processes asynchronously.", "desks": ["swe"], "img": "https://cdn-images-1.medium.com/max/1400/1*WbO6Ymjx6HtI8dD5yIC20g.png", "cap": "REST API vs gRPC — kopi C vs flat white. Both delicious, but not the same. Image generated by Nano Banana", "mins": 9}, {"title": "A Crash Course in Asynchronous Python", "url": "https://medium.com/@tituslhy/a-crash-course-in-asynchronous-python-12e0cc523033", "date": "2025-09-22", "words": 2558, "dek": "Explains Python synchronous and asynchronous functions, using asyncio for I/O concurrency and threads or process pools for CPU parallelism.", "open": "Ever looked at your seniors’ Python code and seen async and await everywhere? Seems simple enough — just add async to a function and await to its call, right? Not quite. Google why, and you’ll often get something like “it doesn’t block the thread so things can run concurrently”.", "desks": ["swe"], "img": "https://cdn-images-1.medium.com/max/1400/1*Vln2ovr9aPyNGjviTf1H7A.png", "cap": "Concurrency, threading and parallelism in Python. Image generated by ChatGPT", "mins": 10}, {"title": "Would you like an agent with that? — Introducing the Deep Agents SDK", "url": "https://medium.com/@tituslhy/would-you-like-an-agent-with-that-introducing-the-deep-agents-sdk-c4e0670440ea", "date": "2025-09-05", "words": 2265, "dek": "Demonstrates building and comparing LangChain Deep Agents with planning and filesystem tools and subagents, using a ReAct agent as a baseline for research reports.", "open": "In Act One of this series, we served a Qwen3 8Bn reasoning LLM with vLLM and scaled it using Bento Cloud — all in Python. In Act Two, we turned that LLM into a full retrieval-augmented generation (RAG) service with Qdrant Cloud and Llama Cloud. Thanks to Llama Parse, even diagrams, charts, and tables became instantly RAG-ready.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*7R63gLPT1vxGeLw7nmKwng.png", "cap": "Special agent reporting for duty. Image generated by ChatGPT", "mins": 10}, {"title": "🦙 Would You Like Context With That? — A RAG-as-a-Service Drive-Thru", "url": "https://medium.com/@tituslhy/would-you-like-context-with-that-a-rag-as-a-service-drive-thru-2e5a2867102a", "date": "2025-08-27", "words": 2549, "dek": "Builds an advanced retrieval-augmented generation application using Llama Cloud for document indexing and Qdrant Cloud for vector search, then connects and deploys it with Python.", "open": "In Act One of this series, we served a Qwen3 8Bn reasoning LLM using the vLLM framework. We then extended its capabilities by spinning up and orchestrating replicas with Bento Cloud — all using just Python. In a previous article, I shared that vLLM is by far the most performant way to serve an LLM, thanks to its KV-caching capabilities.", "desks": ["rag"], "img": "https://cdn-images-1.medium.com/max/1400/1*fVQ-O-6DFJ5DvkbJ-uptwg.png", "cap": "Special context delivery. Image generated by ChatGPT", "mins": 11}, {"title": "🥡 Would you like an LLM with that? — A Bento Cloud Drive-Thru", "url": "https://medium.com/@tituslhy/would-you-like-an-llm-with-that-a-bento-cloud-drive-thru-7e70f77277d2", "date": "2025-08-23", "words": 2376, "dek": "Demonstrates deploying a Qwen3 vLLM model as a BentoML service on Bento Cloud, using replicas and autoscaling to serve scalable GenAI applications.", "open": "The generative AI space sometimes feels like a buffet – dozens of dishes that all taste suspiciously similar. By day, I’m using LangChain and my team’s go-to stack for LLMs, vector databases, and observability. By night, I use LlamaIndex and tinker with whatever shiny new toy catches my eye.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*soI-1k8sFVkVaQLupPO5pw.png", "cap": "The most epic grilled cheese sandwich in the most epic bento. Image generated by ChatGPT", "mins": 10}, {"title": "Building “prompt-free” generative AI applications with DSPy", "url": "https://medium.com/@tituslhy/building-prompt-free-generative-ai-applications-with-dspy-cdda61dcc861", "date": "2025-08-13", "words": 2504, "dek": "Demonstrates using DSPy signatures and workflows with local GPT-OSS to handle document summarization and question answering, then explores automated prompt optimization and evaluation.", "open": "Ask anyone who’s used a generative AI app, and they’ll tell you: large language models (LLMs) can be inconsistent — sometimes returning wildly different answers to the exact same question. Ask anyone who builds these apps or trains the LLMs, and… you’ll hear the same story.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*4dI21G0a4usibOQLk4MKog.png", "cap": "Using DSPy feels like riding a bicycle while everyone else walks — but look up: there’s a parrot plane, a Llama Metro, and a GPU car. Image generated by ChatGPT", "mins": 11}, {"title": "The Discovery Channel: Introducing Nacos Registry", "url": "https://medium.com/@tituslhy/towards-general-discoverability-introducing-nacos-registry-60fa2e1a8731", "date": "2025-08-07", "words": 2326, "dek": "Demonstrates using Alibaba Nacos for service discovery, health checks, routing, and monitoring of MCP and ACP agent services, including a Docker Compose setup with Prometheus and Grafana.", "open": "The model context protocol (“MCP”) has been the toast of the generative AI space since its launch by Anthropic. _Its ability to let users_ _connect and disconnect tools with a few clicks_ _introduced a new level of_ _interoperability__, transforming how agents interact with tools.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*ifX_KrkGKFZUg7_0ujfNXg.png", "cap": "Registry services enable discoverability: Image generated by ChatGPT", "mins": 10}, {"title": "Building your first multi-agent system with n8n", "url": "https://medium.com/@tituslhy/building-your-first-multi-agent-system-with-n8n-0c959d7139a1", "date": "2025-07-30", "words": 2510, "dek": "Shows how to build an n8n multi-agent workflow with Llama Guard safety checks, structured task routing, specialist agents, and consolidated responses.", "open": "In my previous article, I showed how to build a fully functional generative AI agent service on n8n — with zero code. That agent could access Google Calendar, respond to queries, and even update or create events. We then took it a step further: instead of triggering the workflow manually, we configured it to be callable as a sub-workflow — effectively turning it into a reusable tool.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*3L-APKiwo4r43HQGmdAlSg.png", "cap": "An n8n multi-agent system. Image generated by ChatGPT", "mins": 12}, {"title": "Building your first no code agent with n8n", "url": "https://medium.com/@tituslhy/building-your-first-no-code-agent-with-n8n-e9e9ea0c23d1", "date": "2025-07-27", "words": 2109, "dek": "Demonstrates building a no-code AI agent in n8n by connecting an LLM, memory, and Google Calendar, then exposing and reusing the workflow.", "open": "It’s almost August 2025, and generative AI isn’t just a trend — it’s part of everyday life. Teenagers use ChatGPT for homework, students turn to Notebook LM to prep for exams, WhatsApp users have instant access to the Meta AI chatbot, developers lean on GitHub Copilot, and business professionals interact with Microsoft Copilot across Office tools.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*2ampD4v1ycHO8GUog4DPdQ.png", "cap": null, "mins": 9}, {"title": "Service please 👨🏻‍🍳 : 3 ways to serve an LLM", "url": "https://medium.com/@tituslhy/service-please-3-ways-to-serve-an-llm-ca5ead2547e6", "date": "2025-07-22", "words": 2856, "dek": "Compares Ollama, Docker Model Runner, and vLLM for hosting open-source LLMs behind OpenAI-compatible APIs, covering setup, tradeoffs, and a Colab deployment.", "open": "The generative AI space has mushroomed by leaps and bounds since ChatGPT’s launch on 30 Nov 2022. Today, there are not only more LLM service providers — but also an exciting number of open-source models that match or even outperform their closed-source counterparts.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*lmEDKbyo6vFoRkNprkD3wg.png", "cap": "LLMs served 3 ways — like eggs. Image generated by ChatGPT", "mins": 12}, {"title": "A gentle introduction to LiteLLM", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-litellm-649d48a0c2c7", "date": "2025-07-11", "words": 2638, "dek": "Explains using LiteLLM’s SDK and Kubernetes proxy to unify LLM provider APIs, deploy and manage models, track usage, and integrate with agent frameworks.", "open": "Imagine this scenario: > You’re part of a generative AI team at a company with access to every major LLM on the market. You’ve even fine-tuned and deployed a few models locally for proprietary use cases. > But every month, your team’s cloud budget is getting wrecked.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*iCf7HWOuARpblDKGiN-3IA.png", "cap": "Introducing LiteLLM. Image generated by ChatGPT", "mins": 11}, {"title": "Practice vs Theory: Software development at the workplace", "url": "https://medium.com/@tituslhy/practice-vs-theory-software-development-at-the-workplace-a73e676e58c8", "date": "2025-06-27", "words": 2584, "dek": "Compares classroom Agile and DevSecOps practices with workplace software development, explaining how lean teams handle project planning, Git workflows, testing, CI/CD, and code review differently.", "open": "Like most of my classmates, I’m a proud graduate of the Master of IT in Business (MITB) AI track program at the Singapore Management University. One of my favorite electives was a breadth module outside my AI focus — Agile and DevSecOps, from the Digital Transformation track.", "desks": ["career"], "img": "https://cdn-images-1.medium.com/max/1400/1*5XIq61o7WQUD18_h8mP3JQ.png", "cap": "Classroom vs the office. Image generated by ChatGPT", "mins": 10}, {"title": "Living with imposter syndrome", "url": "https://medium.com/@tituslhy/living-with-imposter-syndrome-193adff0a825", "date": "2025-06-24", "words": 2706, "dek": "The author explains practical ways to manage imposter syndrome through small actions, selective feedback, self-compassion, and celebrating progress, illustrated with software and AI project experiences.", "open": "Have you ever felt like a fraud at your own job? That sinking feeling that everyone around you is going to discover you have no idea what you’re doing? That’s imposter syndrome — and it’s something I wrestle with often. It’s worst when you have past failures to back it up.", "desks": ["career"], "img": "https://cdn-images-1.medium.com/max/1400/1*z9IWxC3wSdCRKwIZgqg_Xg.png", "cap": "Feeling like an imposter despite your abilities? Image generated by ChatGPT", "mins": 10}, {"title": "How to Deploy (Almost) Any LangChain Runnable in One Line", "url": "https://medium.com/@tituslhy/how-to-deploy-almost-any-langchain-runnable-in-one-line-70e7ec1240d1", "date": "2025-06-18", "words": 1743, "dek": "Demonstrates deploying a LangChain runnable as a REST API with LangServe, using a Llama Guard text-moderation chain and discussing its playground and framework integrations.", "open": "Since its launch into the burgeoning generative AI space in October 2022, LangChain has achieved a cult following. At that time, it was the only framework that could reliably orchestrate LLM application components. It is now 2025 and the framework has a staggering 110k GitHub stars, making it one of the most popular frameworks to ever exist on GitHub.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/0*KwOXo5qS6o1L75Fj", "cap": "Serve your app. Image generated by ChatGPT", "mins": 8}, {"title": "How to build your own change data capture pipeline using Apache Airflow", "url": "https://medium.com/@tituslhy/how-to-build-your-own-change-data-capture-pipeline-using-apache-airflow-e485fbef82c7", "date": "2025-06-17", "words": 2565, "dek": "Builds an Apache Airflow change-data-capture pipeline that tracks document updates and incrementally ingests new or changed files into a Qdrant vector database for RAG.", "open": "Data scientists build machine learning models that power many of the apps we use today. But any data scientist will very quickly tell you that the most important thing isn’t the model, it’s the data. > As the age-old saying goes: Garbage in garbage out. This goes for any generative AI application as well.", "desks": ["swe"], "img": "https://cdn-images-1.medium.com/max/1400/0*d69cxXh0QpjE-hNW", "cap": "Sleep is for the weak — data engineering for the brave. Image generated by ChatGPT", "mins": 11}, {"title": "Agent Memory: The underrated superpower of agentic apps", "url": "https://medium.com/@tituslhy/agent-memory-the-underrated-superpower-of-agentic-apps-1c16fb47f435", "date": "2025-06-16", "words": 2473, "dek": "Explains persistent agent memory as retrieval-augmented context, compares LangMem and LlamaIndex approaches, and demonstrates integrating Mem0 into an agent app.", "open": "It’s 2025, and “agentic applications” have taken center stage in the generative AI landscape. These autonomous agents can now plan, reason, and act — using tools, APIs, and knowledge bases to complete complex tasks. We’ve seen a surge of innovation: tool and agent interoperability protocols, orchestration frameworks, etc.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*EaOz0Wg_Q-yYnb_HwIfRSg.png", "cap": "My agent remembers! Image generated by ChatGPT", "mins": 10}, {"title": "Think Your RAG App Is Safe? Giskard Might Prove You Wrong", "url": "https://medium.com/@tituslhy/think-your-rag-app-is-safe-giskard-might-prove-you-wrong-6c88b08c5f7a", "date": "2025-06-13", "words": 2593, "dek": "Evaluates a LlamaIndex RAG system with quality metrics and Giskard red-team tests, examining robustness limits, score tradeoffs, and layered defenses against attacks.", "open": "Large language models (LLMs) are amazing. Trained on vast corpora, they can converse fluently on many topics. But ask them about your internal knowledge base and things will quickly go off the rails — not only might the answer be wrong, it will likely be delivered with alarming confidence.", "desks": ["eval"], "img": "https://cdn-images-1.medium.com/max/1400/1*CSe0ED6QPE-6ILzjvTlcUQ.png", "cap": "Redteaming an LLM agent. Image generated by ChatGPT", "mins": 11}, {"title": "Text-to-SQL Just Got Easier: Meet Vanna AI, Your Text-to-SQL Assistant", "url": "https://medium.com/@tituslhy/text-to-sql-just-got-easier-meet-vanna-ai-your-rag-powered-sql-sidekick-e781c3ffb2c5", "date": "2025-06-12", "words": 2070, "dek": "Demonstrates building a natural-language-to-SQL application over Yahoo Finance stock data using Vanna AI, vector-based retrieval-augmented generation, and a Chainlit interface.", "open": "When ChatGPT launched in late 2022, it felt like generative AI had appeared out of nowhere. Suddenly, we had human-like conversations with a machine — and surprisingly accurate answers across a wide range of topics. One of the earliest practical use cases that emerged was retrieval augmented generation (RAG).", "desks": ["rag"], "img": "https://cdn-images-1.medium.com/max/1400/1*AYbk4Z1f9MbKErYdAkb6FA.png", "cap": "Text-to-SQL illustrated. Image generated by ChatGPT", "mins": 9}, {"title": "Introducing the Agent Communication Protocol (ACP)", "url": "https://medium.com/@tituslhy/introducing-the-agent-communication-protocol-acp-abd882114139", "date": "2025-06-09", "words": 2195, "dek": "Builds and deploys a retrieval-augmented generation agent with IBM’s Agent Communication Protocol, then explores agent discovery and interoperability through BeeAI and related protocols.", "open": "If you’ve been exploring the generative AI space, you’ve probably come across two foundational ideas: the Model Context Protocol (MCP) and the Agent-to-Agent (A2A) protocol The MCP — proposed by Anthropic — is like a universal USB port for agent tools, allowing standardized tool usage across different agent frameworks.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*TPW1w23XiP87WgkpnWEqng.png", "cap": "A group chat with a LlamaIndex agent (deployed using ACP) and a LangChain agent (deployed by A2A). Image generated by ChatGPT", "mins": 9}, {"title": "A Guide to Code Testing RAG Agents Without Real LLMs or Vector DBs", "url": "https://medium.com/@tituslhy/a-guide-to-code-testing-rag-agents-without-real-llms-or-vector-dbs-51154ad920be", "date": "2025-06-05", "words": 2126, "dek": "Demonstrates unit-testing a LlamaIndex RAG agent with Pytest and mocks, replacing document readers, LLMs, and vector databases to test setup, execution, and streaming without external calls.", "open": "Testing is essential in software development — it helps catch bugs early and ensures reliability before code reaches production. Traditional software testing focuses on “units” of code, hence the term _unit testing_. These tests are often deterministic: assert func(a, b) == c.", "desks": ["eval"], "img": "https://cdn-images-1.medium.com/max/1400/1*fq0yhh1hmRTg2rLKxt6r0g.png", "cap": "Practice feeding a llama by first feeding a paper llama. Image generated by ChatGPT", "mins": 8}, {"title": "Federated Supervised Finetuning using Flower AI", "url": "https://medium.com/@tituslhy/how-to-train-your-llm-simultaneously-with-10-different-teachers-ba556d4ed2c1", "date": "2025-06-03", "words": 2203, "dek": "Demonstrates federated supervised fine-tuning of an LLM with Flower, keeping datasets local while clients train model updates that a server aggregates across rounds.", "open": "Yup, you read that right. Following our previous articles on supervised finetuning (SFT), retrieval-augmented finetuning (RAFT), and group relative policy optimization (GRPO) of a large language model (“LLM”) we’re taking things even further. Imagine this: you work at a multinational healthcare corporation with hospitals across several jurisdictions.", "desks": ["train"], "img": "https://cdn-images-1.medium.com/max/1400/1*7XTqCHcmFwHyB0WFsQ3srQ.png", "cap": "Toothless learns how to fly, breathe fire and bite at the same time! Image generated by ChatGPT", "mins": 9}, {"title": "How to train your LLM to reason: GRPO reinforcement learning using Unsloth!", "url": "https://medium.com/@tituslhy/how-to-train-your-llm-to-reason-grpo-reinforcement-learning-using-unsloth-64af5e82ac3c", "date": "2025-05-31", "words": 2902, "dek": "Explains GRPO and uses Unsloth with custom reward functions to fine-tune a Llama 3.2 1B model for reasoning, then tests its reasoning and RAG performance.", "open": "> Author’s Note: My profuse thanks to James Koh, PhD for proof reading my explanation on the reinforcement learning algorithms and offering helpful suggestions to make it sharper! Dr. James teaches reinforcement learning at the graduate level at the Singapore Management University.", "desks": ["train"], "img": "https://cdn-images-1.medium.com/max/1400/1*i6xESMXGNYCCV_DJvEnv6w.png", "cap": "Training your LLM to reason is like training your dragon to breathe fire. Image generated by ChatGPT with author’s prompt", "mins": 12}, {"title": "How to RAFT your LLM: Retrieval Augmented Finetuning using Unsloth!", "url": "https://medium.com/@tituslhy/how-to-raft-your-llm-retrieval-augmented-finetuning-using-unsloth-4c3844a9a6e3", "date": "2025-05-22", "words": 2426, "dek": "Demonstrates using Unsloth to fine-tune a Llama 3.2 1B model with retrieval-augmented training examples containing relevant and distracting context, then evaluate it in RAG mode.", "open": "Training a large language model (LLM)is like teaching Toothless to fly in _How to Train Your Dragon_. In our previous article, we tried to teach Toothless to bite — by finetuning our Llama 3.2 1B model on a synthetic dataset derived from a knowledge article on non-traditional credentials.", "desks": ["train"], "img": "https://cdn-images-1.medium.com/max/1400/1*AlV3s7Dwy34whH5AXRe5RA.png", "cap": "Flying for the first time. Image generated by ChatGPT using the author’s prompt", "mins": 10}, {"title": "How to Train Your LLM: Low Rank Adaptation Finetuning using Unsloth!", "url": "https://medium.com/@tituslhy/how-to-train-your-llm-teaching-toothless-to-bite-8d9f56fe4b2a", "date": "2025-05-17", "words": 2657, "dek": "Demonstrates supervised fine-tuning of a language model on custom data with LoRA and Unsloth, covering dataset preparation, evaluation, and local deployment with Ollama.", "open": "Training a large language model can feel a lot like trying to train Toothless to fly in _How to Train Your Dragon_. With Toothless, you’ve clearly got a powerful dragon — but it’s missing a tail wing. Likewise, a base LLM might look impressive, but without training or access to your domain knowledge, it tends to hallucinate and give unreliable replies.", "desks": ["train"], "img": "https://cdn-images-1.medium.com/max/1400/1*eg1Wtx6ey61x-5y7ELPLrg.png", "cap": "Finetuning an LLM is like training a dragon. Image generated by ChatGPT using author’s prompt", "mins": 11}, {"title": "GraphRAG for the win?", "url": "https://medium.com/@tituslhy/graphrag-for-the-win-c19d580debd7", "date": "2025-05-16", "words": 2295, "dek": "Demonstrates a LangChain and Neo4j GraphRAG pipeline that crawls articles, builds a knowledge graph, combines vector and entity search, and examines practical drawbacks.", "open": "The use of knowledge graphs to augment traditional vector-based retrieval-augmented generation (RAG) isn’t new — but it remains far less mainstream than purely vector-based approaches. This raises a natural question: does GraphRAG meet a real need, or is it still just a hidden gem waiting to be polished — if ever?", "desks": ["rag"], "img": "https://cdn-images-1.medium.com/max/1400/0*d8NwNsJHlVG4c_XM.jpg", "cap": "Good idea? Image extraced from vecteezy", "mins": 9}, {"title": "Take your LLM apps to the next level with Chainlit!", "url": "https://medium.com/@tituslhy/its-2025-take-your-llm-apps-to-the-next-level-with-chainlit-00036c8db1ba", "date": "2025-05-05", "words": 2278, "dek": "A tutorial extends a Chainlit LLM chat app with DALL·E image generation, audio transcription and speech, file-based AutoRAG, MCP tool connections, and deployment options.", "open": "In my previous article, I wrote about how to build a generative AI assistant with Google Map capabilities from the ground up. We did some amazing things: - Built an app to support the entire chat lifecycle: login, start chat, handle incoming messages, stop tasks, resume chats, and logout - Added chat starters to help users kick off conversations - Created chat profiles to inject different system prompts for our LLM agent - Implemented chat settings to allow advanced configuration (e.g.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*q6gB9tp5bqVVicmM_SfqlA.png", "cap": "Typing’s too slow, use a mic! Image generated by ChatGPT using author’s image", "mins": 10}, {"title": "It’s 2025 — Start using Chainlit for your LLM Apps", "url": "https://medium.com/@tituslhy/its-2025-start-using-chainlit-for-your-llm-apps-558db1a46315", "date": "2025-05-03", "words": 2389, "dek": "A hands-on guide to building LLM chat applications with Chainlit, covering streaming responses, chat lifecycle features, user login, settings, profiles, and custom canvas integration.", "open": "_Part 1: I love Streamlit but I use Chainlit exclusively for LLM apps (and you should too)_ If you’ve read my previous articles, you’ll know I often explore agentic applications — and you’ve probably noticed one tool keeps surfacing: Chainlit. That’s no accident.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*RpRmbHZQunS3sGEIvg-TAQ.png", "cap": "Building a chatbot app is easier than you think. Image generated by ChatGPT using author’s prompt", "mins": 10}, {"title": "Agent-to-Agent protocols: A story still being written!", "url": "https://medium.com/@tituslhy/agent-to-agent-protocols-a-story-still-being-written-e7e1ffbf3e80", "date": "2025-04-21", "words": 1633, "dek": "Explains the early A2A protocol through code for deploying a currency exchange agent that uses an MCP tool, LlamaIndex, and a custom task manager.", "open": "Like the Model Context Protocol (MCP), the Agent-to-Agent (A2A) protocol has sparked widespread excitement in the generative AI space. Despite being just 12 days old at the time of writing (launched on April 9, with today being April 21) and lacking an official Python SDK, A2A is already generating buzz.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*1SwVQ53IZuoD5MHaUHba8w.png", "cap": "A generated image of my envisioned A2A deployment, created by ChatGPT using my own prompt.", "mins": 7}, {"title": "Model Context Protocol — Hype or necessity?", "url": "https://medium.com/@tituslhy/model-context-protocol-hype-or-necessity-998874d95bc6", "date": "2025-04-20", "words": 2346, "dek": "Explains how to build and deploy Model Context Protocol servers with FastMCP, integrate them with FastAPI and AI applications, and assess MCP’s role in standardizing tool access.", "open": "The model context protocol (“MCP”) has been the toast of the generative AI space since its launch by Anthropic. In its wake, a wave of technical articles have emerged, showcasing “homemade” MCPs coded from scratch, alongside official implementations released by major frameworks.", "desks": ["agents2"], "img": "https://cdn-images-1.medium.com/max/1400/1*Kyz6xXujZCPwPVUGNDXWKQ.png", "cap": "The tool and LLM universal switch: extracted from https://blog.promptlayer.com/mcp/", "mins": 10}, {"title": "How I became a data scientist", "url": "https://medium.com/@tituslhy/how-i-became-a-data-scientist-2d8831531a4c", "date": "2025-04-16", "words": 2420, "dek": "A chemical engineer describes moving from manual spreadsheet work to coding, automating reports and forecasts with VBA before learning Python, SQL, and R for data science.", "open": "_TLDR:_ _I swore I‘d never code. Guess what I do now?_ _PS: My profuse gratitude to the people (friends, professors, instructors, colleagues, bosses) that featured in this story — you know who you are. Without any of you, there is no story to tell._ I graduated as a chemical engineer into a gloomy economy in 2015.", "desks": ["career"], "img": "https://cdn-images-1.medium.com/max/1400/1*Adm1JhcfuYIrMvTXeOxHzg.png", "cap": "A portrait of my odyssey of becoming a data scientist. Image generated by ChatGPT from author’s prompt and image", "mins": 9}, {"title": "CrewAI — Part 4 of LLM Multi-Agents series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multi-agent-multiverse-part-4-crewai-147ada6db54c", "date": "2025-01-22", "words": 2695, "dek": "A tutorial builds CrewAI multi-agent workflows for job search, resume analysis, and interview preparation, then compares orchestration frameworks and discusses deployment.", "open": "_Author’s note: This article was written with some of my friends in mind. The turbulent economy has been tough on them, and I want to remind them to “hang in there” — what’s gold will always shine. I hope this piece inspires you to explore how generative AI can enhance your job search and rekindle the joy of building and discovering._ This article concludes our gentle introduction to the multi-agent multiverse series.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*Y9kyV2ld9cNgZDqOFruZTg.jpeg", "cap": "Competitive rowing crew. Image generated by MetaAI through the Author’s prompt", "mins": 11}, {"title": "Deploying LlamaIndex — Part 3b of LLM Multi-Agents series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multi-agent-multiverse-part-3b-deploying-llamaindex-workflows-df18381d36b9", "date": "2024-11-22", "words": 1581, "dek": "Demonstrates user authentication and feedback in LlamaIndex workflows, then explains deploying and scaling multi-agent workflows with llama-deploy.", "open": "This article continues our exploration of LlamaIndex workflows, an integral part of the _Gentle Introduction to the Multi-Agent Multiverse_ series. The multiverse of multi-agent systems is brimming with exciting frameworks — at least six prominent ones, including LangGraph, Autogen, LlamaIndex, CrewAI, CAMEL, and OpenAI Swarm.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*WKwZiSTCeGjM3mZ6LE8VUg.jpeg", "cap": "Super llamas lead the way. Image generated by Freepik based on a prompt by the author", "mins": 7}, {"title": "LlamaIndex Workflows — Part 3a of LLM Multi-Agents series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multi-agent-multiverse-part-3a-llamaindex-workflows-c0f614c15b88", "date": "2024-11-14", "words": 1536, "dek": "Demonstrates LlamaIndex event-driven workflows for coordinating multi-agent LLM systems, combining an investment definitions agent with an Apple SEC-report RAG agent backed by Qdrant.", "open": "In our previous articles, we explored LangGraph and Autogen in a series dedicated to multi-agent LLM systems. We left off with Autogen in the midst of an exciting shift — rewriting its framework to embrace an event-driven workflow architecture. This approach is widely known in contexts like robotic process automation (RPA), where, for example, uploading a document to a folder can trigger a bot to draft an email summarizing the document for user review.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*25Xia3ZhQ736X4isAegygA.jpeg", "cap": "Llamas lead the way. Image generated by Freepik from the author’s prompt", "mins": 6}, {"title": "Autogen — Part 2 of LLM Multi-Agents series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multi-agent-multiverse-part-2-autogen-5401a0075d75", "date": "2024-11-06", "words": 2310, "dek": "Introduces Microsoft AutoGen’s multi-agent framework by building an Illumina stock-analysis report with group chats and tool-calling agents.", "open": "This article is the second instalment in our series on the LLM multi-agent multiverse. After exploring Langgraph and its impressive capabilities in the previous article, we now continue our journey with Autogen, a multi-agent orchestration library developed by Microsoft.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*a0pVicGjkkOXvuCzm1nZ6g.jpeg", "cap": "Group chat…with agents! Image generated using Freepik AI with author’s prompt", "mins": 10}, {"title": "Langgraph — Part 1 of LLM Multi-Agents series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multi-agents-multiverse-part-1-langgraph-2ac56f1b5b3c", "date": "2024-11-01", "words": 2677, "dek": "A tutorial builds a stateful LangGraph personal assistant by coordinating manager, web-search, and coding agents in a directed workflow.", "open": "Just when it seemed the ‘Multiverse’ saga for LLM orchestration libraries (LangChain, Haystack, LlamaIndex) had concluded, we take a deeper dive down the rabbit hole! With recent advancements in the LLM ecosystem, 2023 marked the year of RAG, while 2024 is shaping up to be the year of agents — not just single agents, but entire agent orchestras.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*IA9_UpMat_jd-uU6PNEn1Q.jpeg", "cap": "There are so many of them! Image generated by Freepik based on the author’s prompt", "mins": 11}, {"title": "LlamaIndex — Part 3 of LLM series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multiverse-part-3-llamaindex-798344050c49", "date": "2024-10-24", "words": 2262, "dek": "Demonstrates LlamaIndex for LLM chat, structured prediction, routing, tool calling, RAG, and agents, then compares its developer experience and capabilities with LangChain and Haystack.", "open": "The rise of Large Language Models (LLMs) has introduced a new challenge: efficiently orchestrating complex interactions while ensuring scalability. This is where LLM orchestration libraries come into play. In this article, we conclude our trilogy on these essential tools by introducing LlamaIndex — a strong contender to the LangChain and Haystack orchestration libraries.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*4AThbiqqAf4S0va7S0COlw.jpeg", "cap": "LlamaIndex, Haystack and LangChain are perfect competitors with distinctive differences. Image generated using Freepik from the author’s prompt", "mins": 9}, {"title": "Haystack — Part 2 of LLM series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multiverse-part-2-haystack-c6af2548df04", "date": "2024-10-12", "words": 2283, "dek": "A tutorial demonstrates using Haystack to orchestrate LLMs for structured prediction, prompt pipelines, classification routing, tool calling, retrieval-augmented generation, and agents.", "open": "If you’ve seen _Spider-Man: No Way Home_, you’ll remember the moment that three versions of Spider-Man — each from a different universe — appear on screen. They all have similar abilities (even the same costume), but each brings their unique style and approach to saving the day.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*TyTyLwEfwoVctvlEp3k8Nw.jpeg", "cap": "Image extracted from stablediffusionweb.com", "mins": 9}, {"title": "Langchain — Part 1 of LLM series", "url": "https://medium.com/@tituslhy/a-gentle-introduction-to-the-llm-multiverse-part-1-langchain-023a899d294e", "date": "2024-10-06", "words": 1859, "dek": "Introduces LangChain through examples of invoking LLMs, structured prediction, tool calling, retrieval-augmented generation, and building a basic agent.", "open": "If you’re just starting on your LLM journey, you will find yourself overwhelmed by the many different (and endless) technology stacks and tools. Worst still, they all seem to do the same thing! There are many vector database vendors, graph database vendors, reranker models, embedding models, LLMs, etc.", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/1*Rk1HrIWy-dum181fvmi38w.jpeg", "cap": "Wait…we are all llamas? Image generated by the author’s prompt using OpenArt", "mins": 7}, {"title": "HyDE (Hypothetical Document Embeddings) for LLM", "url": "https://medium.com/@tituslhy/hyde-and-seek-when-hallucination-leads-the-way-17a9800734fe", "date": "2024-10-02", "words": 1008, "dek": "Demonstrates a LlamaIndex RAG application that uses HyDE-generated hypothetical answers to improve document retrieval and discusses optimizing LLM prompts with DSPy.", "open": "You read the title right. Hallucination is suddenly good when it’s used in RAG applications no less! HyDE isn’t new — the paper was submitted in Dec 2022 and it was quickly implemented in many LLM libraries. The idea is this: Imagine you have a very large knowledge base, as large as a public library.", "desks": ["rag"], "img": "https://cdn-images-1.medium.com/max/1400/1*-nYAp1vjRaJdCiaCSy1kfQ.jpeg", "cap": "Generated by OpenArt based on a prompt by the author", "mins": 5}, {"title": "Multimodal RAG: The promise and premise", "url": "https://medium.com/@tituslhy/video-killed-the-radio-star-a-use-case-for-multimodal-rag-cdb7d5ff3062", "date": "2024-09-25", "words": 602, "dek": "Builds a multimodal RAG system for video lectures by indexing sampled frames and audio transcriptions with LlamaIndex and LanceDB for question answering.", "open": "There have been many articles and cookbook recipes on text-based RAG and deservingly so - RAG allows anyone to “chat” with their lengthy PDFs. Many advanced text RAG techniques exist and it’s amazing how far the field has come! But there are some limitations to text-based RAG.", "desks": ["rag"], "img": "https://cdn-images-1.medium.com/max/1400/1*e2QZ0rgxhPfhkTXJoh1vJg.png", "cap": "Can an LLM play “show and tell”? Image created by DALL·E 3 based on the author’s prompt.", "mins": 3}, {"title": "Investing with LLMs: Does it make cents?", "url": "https://medium.com/@tituslhy/investing-with-llms-does-it-make-cents-496ed6c87458", "date": "2024-09-06", "words": 1570, "dek": "A tutorial builds a LlamaIndex multi-agent investment analysis system with Python tools for financial statements, stock trends, company filings, research, and data analysis.", "open": "LLMs are amazing. They can write essays, answer questions from bespoke data sources, use tools on hand to answer user questions, and are amazing in every “sequence-based” domain (time series forecasting for e.g.). But can you actually make money when using LLMs for investments?", "desks": ["agents"], "img": "https://cdn-images-1.medium.com/max/1400/0*N8pvGddAUURorHo9", "cap": "Photo by Chris Liverani on Unsplash", "mins": 6}, {"title": "Chain reaction: How to create an observable frontend workflow using LlamaIndex and Chainlit", "url": "https://medium.com/@tituslhy/chain-reaction-how-to-create-an-observable-workflow-using-llamaindex-and-chainlit-2b668fb1cee9", "date": "2024-08-28", "words": 1195, "dek": "Builds a Chainlit-visible, event-driven LlamaIndex workflow that compares Tavily-powered web-search answers with answers generated without search, then selects or combines them.", "open": "LlamaIndex is an open-source Python library that provides a modular and extensible framework for building and orchestrating Large Language Models (LLMs) and other AI components. At its core, LlamaIndex aims to make it easier to develop and deploy sophisticated AI applications.", "desks": ["apps"], "img": "https://cdn-images-1.medium.com/max/1400/1*lXk6LMK2x1rTpuGw91FX9w.png", "cap": "Image source: https://www.llamaindex.ai/blog/introducing-workflows-beta-a-new-way-to-create-complex-ai-applications-with-llamaindex. Modified by the author to include Chainlit component", "mins": 5}];
